/* @lc app=leetcode id=2197 lang=kotlin */ class Solution { fun replaceNonCoprimes(nums: IntArray): List<Int> = nums.fold(mutableListOf<Int>()) { s, n -> s.apply { add(n) }.apply { while (size > 1) if (get(size - 2).toLong().let { a -> get(size - 1).toLong().let { b -> generateSequence(a to b) { if (it.second == 0L) null else it.second to it.first % it.second }.last().first.let { g -> if (g > 1) removeAt(size - 1).let { removeAt(size - 1).also { add((a * b / g).toInt()) } }.let { true } else false } } }) continue else break } } }